    {"text": "Hexthorpe Junction", "type": "Location"},
    {"text": "Cherry Tree Lane", "type": "Location"},
    {"text": "St. Leger race meeting", "type": "Other"},
    {"text": "Midland Railway", "type": "Organization"},
    {"text": "Liverpool", "type": "Location"},
    {"text": "Hull", "type": "Location"},
    {"text": "MS & LR", "type": "Organization"},
    {"text": "York", "type": "Location"},
    {"text": "Lord Chief Justice", "type": "Person"},
    {"text": "A.S.L.E.F.", "type": "Organization"},
    {"text": "Sir Edward Watkin", "type": "Person"},
    {"text": "Armagh rail disaster", "type": "Other"},
    {"text": "Northern Ireland", "type": "Location"}
  ],
  "events": [
    {
      "trigger": "accident",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["Hexthorpe rail accident"],
        "Location": ["Hexthorpe railway platform"],
        "Content": ["occurred on 16 September 1887"]
      }
    },
    {
      "trigger": "arriving",
      "type": "Arriving",
      "arguments": {
        "Agent": ["many trains"],
        "Location": ["the town"]
      }
    },
    {
      "trigger": "moved off",
      "type": "Arriving",
      "arguments": {
        "Agent": ["the first train"]
      }
    },
    {
      "trigger": "moved onto",
      "type": "Arriving",
      "arguments": {
        "Agent": ["the second"],
        "Location": ["the platform"]
      }
    },
    {
      "trigger": "came over",
      "type": "Arriving",
      "arguments": {
        "Agent": ["This train"],
        "Location": ["Hexthorpe Junction"]
      }
    },
    {
      "trigger": "lowered",
      "type": "Damaging",
      "arguments": {
        "Patient": ["the 'home ' signal"]
      }
    },
    {
      "trigger": "assumed",
      "type": "Statement",
      "arguments": {
        "Speaker": ["the driver"],
        "Message": ["wrongly , that with no other fixed signals to Cherry Tree Lane his route was clear"]
      }
    },
    {
      "trigger": "said",
      "type": "Statement",
      "arguments": {
        "Speaker": ["the official report"],
        "Message": ["that the first of the flagmen gave no indication and the second gave an ambiguous signal which was seen by the fireman but not properly understood"]
      }
    },
    {
      "trigger": "reported",
      "type": "Statement",
      "arguments": {
        "Message": ["travelling between 35 and 40 m.p.h . when they rounded the curve and saw the Midland train still in the platform"]
      }
    },
    {
      "trigger": "applied",
      "type": "Damaging",
      "arguments": {
        "Agent": ["The driver"],
        "Patient": ["the 'simple ' vacuum brake"]
      }
    },
    {
      "trigger": "threw",
      "type": "Damaging",
      "arguments": {
        "Agent": ["The driver"],
        "Patient": ["the locomotive"]
      }
    },
    {
      "trigger": "trial",
      "type": "Statement",
      "arguments": {
        "Location": ["York"],
        "Details": ["before the Lord Chief Justice"]
      }
    },
    {
      "trigger": "returned",
      "type": "Statement",
      "arguments": {
        "Speaker": ["The jury"],
        "Message": ["a verdict of 'not guilty '"]
      }
    },
    {
      "trigger": "said",
      "type": "Statement",
      "arguments": {
        "Speaker": ["the Lord Chief Justice"],
        "Message": ["... he could not but think that the railway company was seriously to blame for having had in use a brake which not only was not the best in existence , but which was known to be insufficient and liable to break down ''"]
      }
    },
    {
      "trigger": "said",
      "type": "Statement",
      "arguments": {
        "Speaker": ["Sir Edward Watkin"],
        "Message": ["... it was a misfortune that the Lord Chief Justice should have exonerated the driver and fireman ''"]
      }
    },
    {
      "trigger": "sounded",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["the Hexthorpe accident"],
        "Content": ["closely followed by the Armagh rail disaster in Northern Ireland"]
      }
    }
  ]
}
